func testPaisToOneMoedaUsingMoeda(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local Pais
	var foreign Moeda

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, paisDBTypes, true, paisColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Pais struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, moedaDBTypes, false, moedaColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Moeda struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	queries.Assign(&local.MoedaID, foreign.MoedaID)
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.Moeda().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if !queries.Equal(check.MoedaID, foreign.MoedaID) {
		t.Errorf("want: %v, got %v", foreign.MoedaID, check.MoedaID)
	}

	ranAfterSelectHook := false
	AddMoedaHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *Moeda) error {
		ranAfterSelectHook = true
		return nil
	})

	slice := PaisSlice{&local}
	if err = local.L.LoadMoeda(ctx, tx, false, (*[]*Pais)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Moeda == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.Moeda = nil
	if err = local.L.LoadMoeda(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Moeda == nil {
		t.Error("struct should have been eager loaded")
	}

	if !ranAfterSelectHook {
		t.Error("failed to run AfterSelect hook for relationship")
	}
}

func testPaisToOneSetOpMoedaUsingMoeda(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Pais
	var b, c Moeda

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, paisDBTypes, false, strmangle.SetComplement(paisPrimaryKeyColumns, paisColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, moedaDBTypes, false, strmangle.SetComplement(moedaPrimaryKeyColumns, moedaColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &c, moedaDBTypes, false, strmangle.SetComplement(moedaPrimaryKeyColumns, moedaColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	for i, x := range []*Moeda{&b, &c} {
		err = a.SetMoeda(ctx, tx, i != 0, x)
		if err != nil {
			t.Fatal(err)
		}

		if a.R.Moeda != x {
			t.Error("relationship struct not set to correct value")
		}

		if x.R.Pais[0] != &a {
			t.Error("failed to append to foreign relationship struct")
		}
		if !queries.Equal(a.MoedaID, x.MoedaID) {
			t.Error("foreign key was wrong value", a.MoedaID)
		}

		zero := reflect.Zero(reflect.TypeOf(a.MoedaID))
		reflect.Indirect(reflect.ValueOf(&a.MoedaID)).Set(zero)

		if err = a.Reload(ctx, tx); err != nil {
			t.Fatal("failed to reload", err)
		}

		if !queries.Equal(a.MoedaID, x.MoedaID) {
			t.Error("foreign key was wrong value", a.MoedaID, x.MoedaID)
		}
	}
}

